const site=MCM_WEST;
export const mcmActive=campus=>campus.geometryHash===site.geometryHash&&campus.buildings.some(b=>b.id===site.id);
export const mcmLocal=(x,z)=>[site.basisU,site.basisV].map(b=>(x-site.originXZ[0])*b[0]+(z-site.originXZ[1])*b[1]);
export const mcmWorld=(u,v)=>site.originXZ.map((a,i)=>a+u*site.basisU[i]+v*site.basisV[i]);
const distance=(x,y,a,b)=>{
  const dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy)));
  return Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy);
};
function streetHeight(u,v){
  for(const [a,b,c] of site.approachTrianglesUVY){
    const dx=b[0]-a[0],dz=b[1]-a[1],ex=c[0]-a[0],ez=c[1]-a[1],det=dx*ez-dz*ex;
    const ru=u-a[0],rv=v-a[1],s=(ru*ez-rv*ex)/det,t=(dx*rv-dz*ru)/det;
    if(s>=-1e-8&&t>=-1e-8&&s+t<=1+1e-8)return a[2]+s*(b[2]-a[2])+t*(c[2]-a[2]);
  }
  return null;
}
export function createMcmBridgeAccess(campus,radius){
  if(!mcmActive(campus))return null;
  const bridges=site.bridgeParts.map(b=>{
    const [start,lo,end,hi]=b.deck;
    const [railA,railB]=b.edgeRailLimits;
    const stops=[
      ...[railA,railB].map(v=>({a:[start+.15,v],b:[b.facadeU-.05,v],width:.082})),
      ...[lo,hi].map(v=>({a:[b.facadeU-.07,v],b:[end,v],width:.028})),
      {a:[end-.031,lo],b:[end-.031,hi],width:.020},
    ];
    return {...b,start,lo,end,hi,stops};
  });
  const localAt=(x,z)=>{
    if(x<site.originXZ[0]-45||x>site.originXZ[0]-5||Math.abs(z-site.originXZ[1])>15)return null;
    return mcmLocal(x,z);
  };
  return {
    elevation(x,z){
      const p=localAt(x,z);if(!p)return null;
      const [u,v]=p;
      for(const b of bridges)if(u>=b.start-1e-8&&u<=b.end+1e-8&&v>=b.lo&&v<=b.hi){
        const f=Math.max(0,Math.min(1,(u-b.start)/(b.end-b.start)));
        return b.approachY+(b.thresholdY-b.approachY)*f;
      }
      return streetHeight(u,v);
    },
    blocked(x,z){
      const p=localAt(x,z);if(!p)return false;
      const [u,v]=p;
      return bridges.some(b=>u>=b.start-2&&u<=b.end+1&&v>=b.lo-1&&v<=b.hi+1&&
        b.stops.some(({a,b,width})=>distance(u,v,a,b)<radius+width));
    },
    permits(id,x,z){
      const p=localAt(x,z);if(id!==site.id||!p)return false;
      const [u,v]=p;
      return bridges.some(b=>u>=b.start&&u<=b.end&&v>=b.lo&&v<=b.hi);
    },
  };
}
export function mcmWestGeometry(T,campus,pathId){
  if(pathId!==site.pathId||!mcmActive(campus))return null;
  const parts=[site.sidewalk,site.ramp,site.fascia];
  const geometry=new T.BufferGeometry();
  geometry.setAttribute('position',new T.Float32BufferAttribute(parts.flatMap(p=>p.positions),3));
  geometry.setAttribute('uv',new T.Float32BufferAttribute(parts.flatMap(p=>p.uv),2));
  geometry.setIndex(Array.from({length:geometry.attributes.position.count},(_,i)=>i));
  geometry.computeVertexNormals();
  return geometry;
}
